import React, { useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { type CaipChainId } from '@metamask/utils';
import {
  AvatarIcon,
  AvatarIconSeverity,
  AvatarIconSize,
  AvatarNetwork,
  AvatarNetworkSize,
  Box,
  BoxFlexDirection,
  Button,
  ButtonSize,
  ButtonVariant,
  FontWeight,
  Icon,
  IconColor,
  IconName,
  IconSize,
  ModalHeader,
  Text,
  TextColor,
  TextVariant,
} from '@metamask/design-system-react';
import { CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP } from '../../../../../../shared/constants/network';
import { getNetworkIcon } from '../../../../../../shared/lib/network.utils';
import { isEvmChainId } from '../../../../../../shared/lib/asset-utils';
import {
  Modal,
  ModalContent,
  ModalContentSize,
  ModalOverlay,
} from '../../../../component-library';
import { useI18nContext } from '../../../../../hooks/useI18nContext';
import { transitionForward } from '../../../../ui/transition';
import { NETWORKS_ROUTE } from '../../../../../helpers/constants/routes';
import { NetworkListItem } from '../../../../multichain/network-list-item';
import Tooltip from '../../../../ui/tooltip';
import {
  getSelectableChainId,
  useHomeNetworkFilter,
} from './use-home-network-filter';

type HomeNetworkFilterModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onPendingChange?: (isPending: boolean) => void;
};

type NetworkRowProps = {
  name: string;
  iconSrc?: string;
  chainId?: string;
  selected?: boolean;
  disabled?: boolean;
  disabledTooltip?: string;
  endIconName?: IconName;
  onClick: () => void;
  testId: string;
};

export type NetworkSelectionItem = {
  key: string;
  name: string;
  iconName?: IconName;
  iconSrc?: string;
  chainId?: string;
  selected?: boolean;
  disabled?: boolean;
  disabledTooltip?: string;
  endIconName?: IconName;
  onClick: () => void;
  testId: string;
};

export type NetworkSelectionSection = {
  key: string;
  title?: React.ReactNode;
  items: NetworkSelectionItem[];
};

type NetworkSelectionModalProps = {
  isOpen: boolean;
  onClose: () => void;
  title: React.ReactNode;
  sections: NetworkSelectionSection[];
  'data-testid'?: string;
  topItem?: NetworkSelectionItem;
  footerButton?: {
    label: React.ReactNode;
    testId: string;
    iconName?: IconName;
    onClick: () => void;
  };
};

const SectionHeader = ({
  children,
  className = 'px-4 pb-2 pt-4',
}: {
  children: React.ReactNode;
  className?: string;
}) => (
  <Text
    variant={TextVariant.BodyMd}
    color={TextColor.TextAlternative}
    fontWeight={FontWeight.Medium}
    className={className}
  >
    {children}
  </Text>
);

const HomeNetworkFilterRow = ({
  name,
  iconSrc,
  chainId,
  selected = false,
  disabled = false,
  disabledTooltip,
  endIconName,
  onClick,
  testId,
}: NetworkRowProps) => {
  let endAccessory: React.ReactNode;

  if (disabledTooltip) {
    endAccessory = (
      <Tooltip
        position="top"
        title={disabledTooltip}
        wrapperClassName="flex items-center justify-center"
      >
        <Box className="flex items-center justify-center rounded-lg p-1">
          <Icon name={IconName.Info} size={IconSize.Sm} />
        </Box>
      </Tooltip>
    );
  } else if (endIconName) {
    endAccessory = (
      <Box className="flex items-center justify-center rounded-lg p-1">
        <Icon name={endIconName} size={IconSize.Lg} />
      </Box>
    );
  }

  return (
    <Box data-testid={testId}>
      <NetworkListItem
        name={name}
        iconSrc={iconSrc}
        chainId={chainId}
        selected={selected}
        disabled={disabled}
        onClick={disabled ? () => undefined : onClick}
        focus={false}
        endAccessory={endAccessory}
        showEndAccessory={!selected}
      />
    </Box>
  );
};

const NetworkSelectionItemIcon = ({
  name,
  iconName,
  iconSrc,
}: {
  name: string;
  iconName?: IconName;
  iconSrc?: string;
}) => {
  if (iconName) {
    return (
      <AvatarIcon
        iconName={iconName}
        size={AvatarIconSize.Md}
        severity={AvatarIconSeverity.Neutral}
        iconProps={{ color: IconColor.IconDefault }}
      />
    );
  }

  return (
    <AvatarNetwork name={name} src={iconSrc} size={AvatarNetworkSize.Md} />
  );
};

export const NetworkSelectionModal = ({
  isOpen,
  onClose,
  title,
  sections,
  topItem,
  footerButton,
  'data-testid': dataTestId,
}: NetworkSelectionModalProps) => {
  const t = useI18nContext();
  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      isClosedOnOutsideClick
      isClosedOnEscapeKey
      data-testid={dataTestId}
    >
      <ModalOverlay />
      {isOpen ? (
        <ModalContent
          size={ModalContentSize.Sm}
          modalDialogProps={{
            padding: 0,
            className: 'flex h-full flex-col overflow-hidden',
          }}
        >
          <ModalHeader
            onClose={onClose}
            closeButtonProps={{ ariaLabel: t('close') }}
          >
            {title}
          </ModalHeader>
          <Box
            className="min-h-0 flex-1 overflow-y-auto"
            flexDirection={BoxFlexDirection.Column}
          >
            {topItem ? (
              <button
                type="button"
                className={`flex min-h-16 w-full cursor-pointer items-center justify-between border-0 p-4 text-left hover:bg-hover ${
                  topItem.selected ? 'bg-muted' : 'bg-transparent'
                }`}
                data-testid={topItem.testId}
                onClick={topItem.onClick}
              >
                <Box className="flex min-w-0 items-center gap-3">
                  <NetworkSelectionItemIcon
                    name={topItem.name}
                    iconName={topItem.iconName}
                    iconSrc={topItem.iconSrc}
                  />
                  <Text
                    variant={TextVariant.BodyMd}
                    color={TextColor.TextDefault}
                    fontWeight={FontWeight.Medium}
                    className="truncate"
                  >
                    {topItem.name}
                  </Text>
                </Box>
                {(topItem.selected || topItem.endIconName) && (
                  <Icon
                    name={
                      topItem.selected
                        ? IconName.Check
                        : (topItem.endIconName as IconName)
                    }
                    size={IconSize.Lg}
                  />
                )}
              </button>
            ) : null}
            {sections.map((section, index) => (
              <Box key={section.key} className="flex flex-col">
                {index > 0 ? (
                  <hr className="mx-4 mt-2 w-[calc(100%-32px)] border-0 border-t border-border-muted" />
                ) : null}
                {section.title ? (
                  <SectionHeader
                    className={index > 0 ? 'px-4 pb-2 pt-4' : undefined}
                  >
                    {section.title}
                  </SectionHeader>
                ) : null}
                {section.items.map(({ key, ...item }) => (
                  <HomeNetworkFilterRow key={key} {...item} />
                ))}
              </Box>
            ))}
          </Box>
          {footerButton ? (
            <Box className="px-4 pt-4">
              <Button
                data-testid={footerButton.testId}
                className="h-12 w-full border-0 bg-muted hover:bg-muted-hover active:bg-muted-pressed"
                size={ButtonSize.Md}
                variant={ButtonVariant.Secondary}
                onClick={footerButton.onClick}
              >
                <Box className="flex items-center justify-center gap-2">
                  {footerButton.iconName ? (
                    <Icon name={footerButton.iconName} size={IconSize.Sm} />
                  ) : null}
                  {footerButton.label}
                </Box>
              </Button>
            </Box>
          ) : null}
        </ModalContent>
      ) : null}
    </Modal>
  );
};

const HomeNetworkFilterModalContent = ({
  onClose,
  onPendingChange,
}: {
  onClose: () => void;
  onPendingChange?: (isPending: boolean) => void;
}) => {
  const t = useI18nContext();
  const navigate = useNavigate();
  const {
    additionalNetworks,
    customNetworks,
    defaultNetworks,
    getDisabledTooltip,
    handleAddNetwork,
    handleSelectAllDefaultNetworks,
    handleSelectNetwork,
    hasOnlyDefaultNetworks,
    isAllDefaultSelected,
    isEvmOnlySelectedAccountGroup,
    isNetworkDisabled,
    isNetworkSelected,
    isPending,
    showTestnets,
    testNetworks,
  } = useHomeNetworkFilter({ onClose, onPendingChange });

  const handleClose = useCallback(() => {
    if (isPending) {
      return;
    }
    onClose();
  }, [isPending, onClose]);

  const handleManageNetworks = useCallback(() => {
    // Don't close the modal first — letting the whole current view (modal
    // included) transition as one view-transition snapshot keeps the motion
    // smooth. The modal's open state resets when the home route unmounts.
    transitionForward(() => navigate(NETWORKS_ROUTE));
  }, [navigate]);

  const sections = useMemo<NetworkSelectionSection[]>(() => {
    const nextSections: NetworkSelectionSection[] = [
      {
        key: 'default-networks',
        title: hasOnlyDefaultNetworks ? undefined : t('defaultNetworks'),
        items: defaultNetworks.map((network) => ({
          disabled: isPending || isNetworkDisabled(network),
          key: network.chainId,
          name: network.name,
          iconSrc: getNetworkIcon(network),
          chainId: getSelectableChainId(network),
          selected: isNetworkSelected(network),
          disabledTooltip: getDisabledTooltip(isNetworkDisabled(network)),
          onClick: () => handleSelectNetwork(network.chainId),
          testId: `home-network-filter-network-${getSelectableChainId(network)}`,
        })),
      },
    ];

    if (customNetworks.length > 0) {
      nextSections.push({
        key: 'custom-networks',
        title: t('customNetworks'),
        items: customNetworks.map((network) => ({
          disabled: isPending || isNetworkDisabled(network),
          key: network.chainId,
          name: network.name,
          iconSrc: getNetworkIcon(network),
          chainId: getSelectableChainId(network),
          selected: isNetworkSelected(network),
          disabledTooltip: getDisabledTooltip(isNetworkDisabled(network)),
          onClick: () => handleSelectNetwork(network.chainId),
          testId: `home-network-filter-custom-${getSelectableChainId(network)}`,
        })),
      });
    }

    if (showTestnets && testNetworks.length > 0) {
      nextSections.push({
        key: 'test-networks',
        title: t('testnets'),
        items: testNetworks.map((network) => ({
          disabled: isPending || isNetworkDisabled(network),
          key: network.chainId,
          name: network.name,
          iconSrc: getNetworkIcon(network),
          chainId: getSelectableChainId(network),
          selected: isNetworkSelected(network),
          disabledTooltip: getDisabledTooltip(isNetworkDisabled(network)),
          onClick: () => handleSelectNetwork(network.chainId),
          testId: `home-network-filter-test-${getSelectableChainId(network)}`,
        })),
      });
    }

    if (additionalNetworks.length > 0) {
      nextSections.push({
        key: 'additional-networks',
        title: t('additionalNetworks'),
        items: additionalNetworks.map((network) => {
          const disabled =
            isPending ||
            (!isEvmChainId(network.chainId as CaipChainId) &&
              isEvmOnlySelectedAccountGroup);

          return {
            key: network.chainId,
            name: network.name,
            iconSrc:
              CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP[
                network.chainId as keyof typeof CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP
              ],
            chainId: network.chainId,
            disabled,
            disabledTooltip: getDisabledTooltip(disabled),
            endIconName: IconName.Add,
            onClick: () => handleAddNetwork(network),
            testId: `home-network-filter-additional-${network.chainId}`,
          };
        }),
      });
    }

    return nextSections;
  }, [
    additionalNetworks,
    customNetworks,
    defaultNetworks,
    getDisabledTooltip,
    handleAddNetwork,
    handleSelectNetwork,
    hasOnlyDefaultNetworks,
    isEvmOnlySelectedAccountGroup,
    isNetworkDisabled,
    isNetworkSelected,
    isPending,
    showTestnets,
    t,
    testNetworks,
  ]);

  return (
    <NetworkSelectionModal
      isOpen
      onClose={handleClose}
      data-testid="home-network-filter-modal"
      title={t('bridgeSelectNetwork')}
      topItem={{
        key: 'all-default-networks',
        name: hasOnlyDefaultNetworks
          ? t('allNetworks')
          : t('allDefaultNetworks'),
        iconName: IconName.Global,
        selected: isAllDefaultSelected,
        onClick: handleSelectAllDefaultNetworks,
        testId: 'home-network-filter-all-default',
      }}
      sections={sections}
      footerButton={{
        label: t('manageNetworksMenuHeading'),
        testId: 'home-network-filter-manage-networks',
        iconName: IconName.Setting,
        onClick: handleManageNetworks,
      }}
    />
  );
};

export const HomeNetworkFilterModal = ({
  isOpen,
  onClose,
  onPendingChange,
}: HomeNetworkFilterModalProps) => {
  return isOpen ? (
    <HomeNetworkFilterModalContent
      onClose={onClose}
      onPendingChange={onPendingChange}
    />
  ) : null;
};
